CREATE OR REPLACE FUNCTION public.reports_north_star(_from date,_to date,_filters jsonb,_as_of timestamptz DEFAULT now()) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,public AS $$ DECLARE result jsonb; BEGIN IF NOT public.reports_can('view_reports') THEN RAISE EXCEPTION 'REPORT_ACCESS_DENIED: Your Reports role does not allow this action.' USING ERRCODE='42501'; END IF;
WITH bounds AS(SELECT _from::timestamp AT TIME ZONE 'Africa/Johannesburg' AS start_at,LEAST((_to+1)::timestamp AT TIME ZONE 'Africa/Johannesburg',_as_of,now()) AS end_at), people AS MATERIALIZED(SELECT r FROM public.reports_people_rows(_from,_to,_filters,_as_of) r), links AS(SELECT l.* FROM public.agency_talent_links l JOIN public.agencies a ON a.id=l.agency_id CROSS JOIN bounds b WHERE l.status<>'revoked' AND l.created_at<b.end_at AND NOT EXISTS(SELECT 1 FROM public.talent_invite_private p WHERE p.invitation_id=l.talent_invitation_id AND p.kind='inert') AND (_filters->>'accounts'='all' OR (a.is_test OR EXISTS(SELECT 1 FROM public.talent_profiles t WHERE t.user_id=l.talent_user_id AND t.is_test))=(_filters->>'accounts'='test')) AND EXISTS(SELECT 1 FROM people p WHERE p.r->>'person_id'=l.talent_user_id::text OR (p.r->>'account_type'='agency_staff' AND EXISTS(SELECT 1 FROM jsonb_array_elements_text(p.r->'agency_ids') x WHERE x.value=l.agency_id::text)))), pairs AS(SELECT l.id,l.talent_user_id,
EXISTS(SELECT 1 FROM public.talent_audit_log e,bounds b WHERE e.actor_id=l.talent_user_id AND e.created_at>=b.start_at AND e.created_at<b.end_at AND e.action IN ('login','vault_document_uploaded','vault_document_moved','vault_document_deleted','vault_folder_created','vault_document_shared')) AS talent_active,
(EXISTS(SELECT 1 FROM public.agency_audit_log e,bounds b WHERE e.agency_id=l.agency_id AND e.created_at>=b.start_at AND e.created_at<b.end_at AND ((e.target_type='talent_link' AND e.target_id=l.id::text) OR (e.target_type='talent_invitation' AND e.target_id=l.talent_invitation_id::text) OR (e.target_type='document' AND EXISTS(SELECT 1 FROM public.talent_shared_documents d WHERE d.id::text=e.target_id AND d.talent_link_id=l.id)))) OR EXISTS(SELECT 1 FROM public.agency_document_requests d,bounds b WHERE d.talent_link_id=l.id AND ((d.created_at>=b.start_at AND d.created_at<b.end_at) OR (d.reviewed_at>=b.start_at AND d.reviewed_at<b.end_at)))) AS agency_active FROM links l)
SELECT jsonb_build_object('total',count(*),'active',count(*) FILTER(WHERE talent_active AND agency_active),'people',COALESCE(jsonb_agg(DISTINCT talent_user_id::text) FILTER(WHERE talent_active AND agency_active AND talent_user_id IS NOT NULL),'[]'::jsonb)) INTO result FROM pairs; RETURN result; END $$;
REVOKE ALL ON FUNCTION public.reports_north_star(date,date,jsonb,timestamptz) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.reports_north_star(date,date,jsonb,timestamptz) TO authenticated;
-- Rollback: revoke this aggregate; existing activity records remain unchanged.
